  @protected
  void sse_encode_render_command_wire(
      RenderCommandWire self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case RenderCommandWire_Text(
          page: final page,
          x: final x,
          y: final y,
          text: final text,
          fontId: final fontId,
          size: final size,
          color: final color,
          style: final style,
          xpos: final xpos
