        sse_encode_u_32(color, serializer);
        sse_encode_i_32(style, serializer);
        sse_encode_list_prim_i_32_strict(xpos, serializer);
      case RenderCommandWire_Rect(
          page: final page,
          x: final x,
          y: final y,
          w: final w,
          h: final h,
          color: final color,
          kind: final kind
        ):
        sse_encode_i_32(1, serializer);
        sse_encode_i_32(page, serializer);
        sse_encode_i_32(x, serializer);
        sse_encode_i_32(y, serializer);
        sse_encode_i_32(w, serializer);
        sse_encode_i_32(h, serializer);
        sse_encode_u_32(color, serializer);
        sse_encode_String(kind, serializer);
      case RenderCommandWire_Line(
          page: final page,
          x1: final x1,
          y1: final y1,
          x2: final x2,
          y2: final y2,
          kind: final kind,
          color: final color,
          width: final width
        ):
        sse_encode_i_32(2, serializer);
        sse_encode_i_32(page, serializer);
        sse_encode_i_32(x1, serializer);
        sse_encode_i_32(y1, serializer);
        sse_encode_i_32(x2, serializer);
        sse_encode_i_32(y2, serializer);
        sse_encode_String(kind, serializer);
        sse_encode_u_32(color, serializer);
        sse_encode_i_32(width, serializer);
      case RenderCommandWire_Image(
          page: final page,
          x: final x,
          y: final y,
          w: final w,
          h: final h,
          shapeId: final shapeId,
          mediaId: final mediaId,
          mediaPath: final mediaPath,
          bytes: final bytes,
          rotation: final rotation,
          cropLeft: final cropLeft,
          cropTop: final cropTop,
          cropRight: final cropRight,
          cropBottom: final cropBottom
        ):
        sse_encode_i_32(3, serializer);
        sse_encode_i_32(page, serializer);
        sse_encode_i_32(x, serializer);
        sse_encode_i_32(y, serializer);
        sse_encode_i_32(w, serializer);
        sse_encode_i_32(h, serializer);
        sse_encode_i_32(shapeId, serializer);
        sse_encode_i_32(mediaId, serializer);
        sse_encode_String(mediaPath, serializer);
        sse_encode_list_prim_u_8_strict(bytes, serializer);
        sse_encode_f_32(rotation, serializer);
        sse_encode_f_32(cropLeft, serializer);
        sse_encode_f_32(cropTop, serializer);
        sse_encode_f_32(cropRight, serializer);
        sse_encode_f_32(cropBottom, serializer);
